/* ===== V129: التلفون — شريط سفلي + رابط مباشر لكل صفحة (#buy) ===== */
(function(){
  const PAGES=[...document.querySelectorAll('.tab[data-page]')].map(t=>[t.dataset.page,t.textContent.replace(/\d+/g,'').trim()]);
  const go=p=>{ const t=document.querySelector('.tab[data-page="'+p+'"]'); if(t) t.click() };
  /* نحفظ آخر صفحة بكل جهاز ونحدّث الرابط */
  document.querySelectorAll('.tab[data-page]').forEach(t=>t.addEventListener('click',()=>{ const p=t.dataset.page;
    try{ localStorage.setItem('safi_lastPage',p) }catch(_){}
    try{ history.replaceState(null,'',p==='cashier'?location.pathname:'#'+p) }catch(_){}
    document.querySelectorAll('#mnav [data-p]').forEach(b=>b.classList.toggle('on',b.dataset.p===p||(b.dataset.p==='more'&&!MAIN.includes(p))));
    const sh=document.getElementById('msheet'); if(sh) sh.hidden=true; }));
  const MAIN=['cashier','orders','buy','store'];
  const nav=document.createElement('nav'); nav.id='mnav'; nav.setAttribute('aria-label','التنقل');
  nav.innerHTML=MAIN.map(p=>{ const n=(PAGES.find(x=>x[0]===p)||[p,p])[1]; return `<button type="button" data-p="${p}">${esc(n)}</button>` }).join('')+`<button type="button" data-p="more">☰ المزيد</button>`;
  document.body.appendChild(nav);
  const sh=document.createElement('div'); sh.id='msheet'; sh.hidden=true;
  sh.innerHTML=`<div class="ms-box"><div class="ms-grid">${PAGES.map(([p,n])=>`<button type="button" data-g="${p}">${esc(n)}</button>`).join('')}</div>
    <div class="ms-act"><button type="button" data-x="close">ختام اليوم</button><button type="button" data-x="num">طباعة أرقام</button></div>
    <p class="ms-tip">رابط المسواك المباشر:<br><b>basraview.net/safi/#buy</b></p></div>`;
  document.body.appendChild(sh);
  nav.addEventListener('click',e=>{ const b=e.target.closest('[data-p]'); if(!b) return; if(b.dataset.p==='more'){ sh.hidden=!sh.hidden; return } go(b.dataset.p) });
  sh.addEventListener('click',e=>{ if(e.target===sh){ sh.hidden=true; return } const g=e.target.closest('[data-g]'); if(g){ go(g.dataset.g); return }
    const x=e.target.closest('[data-x]'); if(x){ sh.hidden=true; const id=x.dataset.x==='close'?'closeBtn':'numBtn'; const btn=document.getElementById(id); if(btn) btn.click() } });
  /* الفتح: الرابط أولاً (#buy)، وإلا آخر صفحة بهذا الجهاز */
  const want=(location.hash||'').slice(1)||(()=>{ try{ return localStorage.getItem('safi_lastPage') }catch(_){ return '' } })();
  if(want&&want!=='cashier'&&document.querySelector('.tab[data-page="'+want+'"]')) setTimeout(()=>go(want),0);
  else nav.querySelector('[data-p="cashier"]').classList.add('on');
  window.addEventListener('hashchange',()=>{ const p=location.hash.slice(1); if(p) go(p) });
})();

const SAFI_VER='V129';
#mnav,#msheet{display:none}
@media(max-width:700px){
  .rail .tabs,.rail .barend .numbtn{display:none !important}
  .rail{justify-content:space-between}
  body{padding-bottom:76px}
  #mnav{display:flex;position:fixed;inset-inline:0;bottom:0;z-index:900;height:66px;padding:6px 6px calc(6px + env(safe-area-inset-bottom));background:#0B0C0E;border-top:1px solid #1F2125;gap:4px}
  #mnav button{flex:1;border:0;border-radius:12px;background:transparent;color:#9296A0;font:inherit;font-size:14.5px;font-weight:600}
  #mnav button.on{background:#1C1E22;color:#F5C04A}
  #msheet:not([hidden]){display:flex;position:fixed;inset:0;z-index:950;background:rgba(0,0,0,.6);align-items:flex-end}
  .ms-box{width:100%;background:#111214;border-radius:20px 20px 0 0;padding:16px 14px calc(84px + env(safe-area-inset-bottom));border-top:1px solid #2a2c33}
  .ms-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
  .ms-grid button,.ms-act button{min-height:56px;border-radius:14px;border:1px solid #2a2c33;background:#17181C;color:#F5F5F2;font:inherit;font-size:15px;font-weight:600}
  .ms-act{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}
  .ms-act button{border-color:#F5C04A55;color:#F5C04A}
  .ms-tip{margin-top:12px;font-size:12.5px;color:#9296A0;text-align:center;line-height:1.7}
  .ms-tip b{color:#C9CCD3;direction:ltr;display:inline-block}
}
